function getPowerShellCommand(show: boolean) {
	const desiredFlag = show ? 1 : 0;
	const showLiteral = show ? "$true" : "$false";

	return [
		'$signature = @"',
		"using System;",
		"using System.Runtime.InteropServices;",
		"public struct POINT { public int X; public int Y; }",
		"public struct CURSORINFO { public int cbSize; public int flags; public IntPtr hCursor; public POINT ptScreenPos; }",
		"public static class CursorNative {",
		'  [DllImport("user32.dll")] public static extern int ShowCursor(bool show);',
		'  [DllImport("user32.dll")] public static extern bool GetCursorInfo(ref CURSORINFO info);',
		"}",
		'"@;',
		"Add-Type -TypeDefinition $signature -Language CSharp -ErrorAction SilentlyContinue | Out-Null;",
		"$info = New-Object CURSORINFO;",
		"$info.cbSize = [Runtime.InteropServices.Marshal]::SizeOf([type]CURSORINFO);",
		"for ($i = 0; $i -lt 32; $i++) {",
		"  if ([CursorNative]::GetCursorInfo([ref]$info) -and (($info.flags -band 1) -eq " +
			desiredFlag +
			")) { exit 0 }",
		"  [CursorNative]::ShowCursor(" + showLiteral + ") | Out-Null;",
		"}",
		"exit 0",
	].join(" ");
}

function runPythonSnippet(code: string) {
	for (const executable of ["python", "python3", "py"]) {
		const result = spawnSync(executable, ["-c", code], { timeout: 5000 });
		if (!result.error && result.status === 0) {
			return true;
		}
	}

	return false;
}

function runPowerShellSnippet(command: string) {
	const result = spawnSync(
		"powershell.exe",
		["-NoProfile", "-NonInteractive", "-WindowStyle", "Hidden", "-Command", command],
		{ timeout: 8000 },
	);

	return !result.error && result.status === 0;
}

let cursorHidden = false;

export function hideCursor() {
	if (process.platform !== "win32" || cursorHidden) {
		return false;
	}

	try {
		const didHide =
			runPythonSnippet(PY_HIDE_WIN) || runPowerShellSnippet(getPowerShellCommand(false));

		if (didHide) {
			cursorHidden = true;
		}

		return didHide;
	} catch (error) {
		console.error("[cursorHider] Failed to hide Windows cursor:", error);
		return false;
	}
}

export function showCursor() {
	if (process.platform !== "win32" || !cursorHidden) {
		return false;
	}

	try {
		const didShow =
			runPythonSnippet(PY_SHOW_WIN) || runPowerShellSnippet(getPowerShellCommand(true));
		if (didShow) {
			cursorHidden = false;
		}
		return didShow;
	} catch (error) {
		console.error("[cursorHider] Failed to show Windows cursor:", error);
		return false;
	}
}

import { describe, expect, it } from "vitest";

import {
	getHudOverlayWindowBounds,
	resizeHudOverlayFallbackBounds,
	shouldExpandHudOverlayFallback,
} from "./hudOverlayBounds";

describe("getHudOverlayWindowBounds", () => {
	const workArea = {
		x: 120,
		y: 40,
		width: 1920,
		height: 1040,
	};

	it("uses the full work area when mouse passthrough is supported", () => {
		expect(getHudOverlayWindowBounds(workArea, true)).toEqual(workArea);
	});

	it("uses a bottom-centered compact fallback when mouse passthrough is unavailable", () => {
		expect(getHudOverlayWindowBounds(workArea, false)).toEqual({
			x: 650,
			y: 920,
			width: 860,
			height: 160,
		});
	});

	it("expands the non-passthrough fallback for HUD menus and hover interaction", () => {
		expect(getHudOverlayWindowBounds(workArea, false, true)).toEqual({
			x: 650,
			y: 540,
			width: 860,
			height: 540,
		});
	});

	it("keeps the compact fallback inside small displays", () => {
		expect(
			getHudOverlayWindowBounds(
				{
					x: -100,
					y: 20,
					width: 640,
					height: 420,
				},
				false,
			),
		).toEqual({
			x: -100,
			y: 280,
			width: 640,
			height: 160,
		});
	});

	it("fits the expanded fallback inside small displays", () => {
		expect(
			getHudOverlayWindowBounds(
				{
					x: -100,
					y: 20,
					width: 640,
					height: 420,
				},
				false,
				true,
			),
		).toEqual({
			x: -100,
			y: 20,
			width: 640,
			height: 420,
		});
	});
});

describe("resizeHudOverlayFallbackBounds", () => {
	const workArea = {
		x: 0,
		y: 0,
		width: 1920,
		height: 1080,
	};

	it("preserves the dragged bottom edge when expanding", () => {
		expect(
